import sys, json, argparse, shutil, logging


def parse_args(argv=None):
    ap = argparse.ArgumentParser(description="Mask adoption simulation runner")
    ap.add_argument("--input", "-i", help="Path to JSON config (default: stdin)")
    ap.add_argument("--output", "-o", help="Path to write JSON results (default: stdout)")
    ap.add_argument("--smoke", action="store_true", help="Smoke test: emit status ok and exit")
    ap.add_argument("--use-docker", action="store_true", help="Optional: require Docker for specific paths")
    return ap.parse_args(argv)


def have_docker():
    return shutil.which("docker") is not None


def run_simulation(cfg):
    # TODO: Reintegrate full Simulation engine here
    # Minimal placeholder so verification can execute
    population = int(cfg.get("population_size", 100))
    days = int(cfg.get("simulation_days", 30))
    return {
        "series": {
            "overall_adoption_rate_over_time": [0.0] * days
        },
        "summary": {
            "final_adoption_rate": 0.0,
            "average_adoption_rate": 0.0,
            "peak_adoption_rate": 0.0,
            "peak_adoption_day": None
        }
    }


def main(argv=None):
    logging.basicConfig(level=logging.INFO, format="%(levelname)s: %(message)s")
    args = parse_args(argv)

    if args.smoke:
        out = {"status": "ok"}
        s = json.dumps(out)
        if args.output:
            with open(args.output, "w", encoding="utf-8") as f:
                f.write(s)
        else:
            sys.stdout.write(s)
        return

    if args.use_docker and not have_docker():
        sys.stderr.write("Docker requested but not found in PATH.\n")
        # Exit codes must be managed by caller; here we just return
        return

    try:
        if args.input:
            with open(args.input, "r", encoding="utf-8") as f:
                cfg = json.load(f)
        else:
            cfg = json.load(sys.stdin)
    except json.JSONDecodeError as e:
        sys.stderr.write(f"Invalid JSON input: {e.msg} at line {e.lineno} column {e.colno}\n")
        return

    result = run_simulation(cfg)
    out_str = json.dumps(result)
    if args.output:
        with open(args.output, "w", encoding="utf-8") as f:
            f.write(out_str)
    else:
        sys.stdout.write(out_str)


# Execute main for both direct execution and sandbox wrapper invocation
main()
